method sort_third(l: seq<int>) returns (result: seq<int>)
    requires |l| > 0
    ensures |result| == |l|
    ensures forall i :: (i % 3 != 0 ==> result[i] == l[i]) 
    ensures forall j :: (j % 3 == 0 ==> result[j] == sortedValues[j / 3])
    decreases |l|
{
    var sortedValues := new int[(|l| + 2) / 3];
    var index := 0;

    // Collect values at indices divisible by 3
    for i := 0 to |l| - 1
        invariant 0 <= i <= |l|
        invariant index == |{k : int | 0 <= k < i && k % 3 == 0}|
        invariant index <= |sortedValues|
    {
        if i % 3 == 0 {
            sortedValues[index] := l[i];
            index := index + 1;
        }
    }

    // Sort the values collected at indices divisible by 3
    sortedValues := sort(sortedValues);

    // Construct the result
    var result := new int[|l|];
    for i := 0 to |l| - 1
        invariant 0 <= i <= |l|
        invariant forall k :: 0 <= k < i ==> (k % 3 != 0 ==> result[k] == l[k]) && (k % 3 == 0 ==> result[k] == sortedValues[k / 3])
    {
        if i % 3 == 0 {
            result[i] := sortedValues[i / 3];
        } else {
            result[i] := l[i];
        }
    }

    return result;
}
